from work import evaluate
p={'edges':{'a>b':{},'b>c':{'role':'admin'},'c>d':{'retry':True},'d>e':{'retry':True,'role':'admin'}},'retry_limit':2}
cases=[({'from':'x','to':'y'},{'ok':False,'value':None,'reason':'blocked'}),({'from':'b','to':'c','role':'user','attempts':False},{'ok':False,'value':None,'reason':'permission'}),({'from':'c','to':'d'},{'ok':False,'value':None,'reason':'retry_limit'}),({'from':'c','to':'d','attempts':False},{'ok':False,'value':None,'reason':'retry_limit'}),({'from':'c','to':'d','attempts':-1},{'ok':False,'value':None,'reason':'retry_limit'}),({'from':'c','to':'d','attempts':0},{'ok':True,'value':'d','reason':'ok'}),({'from':'c','to':'d','attempts':1},{'ok':True,'value':'d','reason':'ok'}),({'from':'c','to':'d','attempts':2},{'ok':False,'value':None,'reason':'retry_limit'}),({'from':'a','to':'b','attempts':99},{'ok':True,'value':'b','reason':'ok'})]
for req,expected in cases:
 rb=copy.deepcopy(req); pb=copy.deepcopy(p); got=evaluate(req,p)
 assert got==expected,(req,got,expected)
